// ============================================================
// Filter projects whose status has changed since last notification
// Compare status vs last_notified_status field
// Also check if updated_at is within the last 12 hours as fallback
// ============================================================
const records = $input.first().json.records || [];
if (records.length === 0) return [];

const now = new Date();
const twelveHoursAgo = new Date(now.getTime() - 12 * 60 * 60 * 1000);

const changed = [];
for (const r of records) {
  const f = r.fields || {};
  const currentStatus = (f.status || '').trim();
  const lastNotified = (f.last_notified_status || '').trim();
  const updatedAt = f.updated_at ? new Date(f.updated_at) : null;

  // Include if status differs from last notified status
  const statusChanged = currentStatus && currentStatus !== lastNotified;
  // Fallback: include if updated recently and no last_notified_status tracked yet
  const recentlyUpdated = !lastNotified && updatedAt && updatedAt > twelveHoursAgo;

  if (statusChanged || recentlyUpdated) {
    changed.push({
      id: r.id,
      brand_name: f.brand_name || 'Unknown Brand',
      client_code: f.client_code || '',
      client_name: f.client_name || '',
      status: currentStatus,
      last_notified_status: lastNotified,
      num_scripts: f.num_scripts || 0,
      deck_link: f.deck_link || '',
      delivery_folder: f.delivery_folder || ''
    });
  }
}

if (changed.length === 0) return [];

// Group by brand
const byBrand = {};
for (const p of changed) {
  if (!byBrand[p.brand_name]) byBrand[p.brand_name] = [];
  byBrand[p.brand_name].push(p);
}

// Build a summary object for Gemini
const brandSummaries = Object.entries(byBrand).map(([brand, projects]) => ({
  brand,
  projects: projects.map(p => ({
    client_code: p.client_code,
    previous_status: p.last_notified_status || 'New',
    current_status: p.status,
    num_scripts: p.num_scripts,
    deck_link: p.deck_link,
    delivery_folder: p.delivery_folder
  }))
}));

return [{ json: {
  changed_projects: changed,
  brand_summaries: brandSummaries,
  total_changed: changed.length
}}];

