// Extract Gemini response text and prepare Slack message
// ============================================================
const geminiResponse = $input.first().json;
const candidates = geminiResponse.candidates || [];
let digestText = '';

if (candidates.length > 0 && candidates[0].content && candidates[0].content.parts) {
  digestText = candidates[0].content.parts.map(p => p.text || '').join('');
}

if (!digestText) {
  digestText = 'No status changes to report.';
}

const changedProjects = $('Filter Changed Projects').first().json.changed_projects || [];
const totalChanged = changedProjects.length;
const now = new Date();
const timeStr = now.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', hour: '2-digit', minute: '2-digit', hour12: true });

const header = `*Smashed Agency — Client Status Digest*\n_${now.toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })} at ${timeStr} IST_\n${totalChanged} project(s) with updates\n\n---\n\n`;

return [{ json: {
  slack_message: header + digestText,
  changed_projects: changedProjects,
  total_changed: totalChanged
}}];

// ============================================================
// Batch update last_notified_status for all changed projects
// Build Airtable batch update payloads (max 10 per request)
// ============================================================
const changedProjects = $json.changed_projects || [];
if (changedProjects.length === 0) return [];

const updates = changedProjects.map(p => ({
  id: p.id,
  fields: {
    last_notified_status: p.status
  }
}));

// Split into batches of 10 for Airtable API
const batches = [];
for (let i = 0; i < updates.length; i += 10) {
  batches.push(updates.slice(i, i + 10));
}

return batches.map(batch => ({ json: { records: batch } }));

parameters.content:
## WEBHOOK PATH
Event-driven updates from other workflows + Orchestrator.
Orchestrator sends: { client_code, brand_name, project_id, message, source: "orchestrator" }
Legacy sends: { event/event_type, project_id, brand_name, client_code, details }
Orchestrator path skips Airtable fetch — uses message directly.
Gemini generates contextual message, posts to Slack, writes event log.

