// ============================================================
// Extract and validate webhook payload
// Accept both legacy (event/event_type) and orchestrator (source) formats
// ============================================================
const body = $input.first().json.body || $input.first().json;
const source = (body.source || '').trim().toLowerCase();
const isOrchestrator = source === 'orchestrator';

// Orchestrator sends: { client_code, brand_name, project_id, message, source }
// Legacy sends: { event/event_type, project_id, brand_name, client_code, details }
const event = (body.event || body.event_type || '').trim().toLowerCase();
const project_id = (body.project_id || '').trim();
const brand_name = (body.brand_name || '').trim();
const client_code = (body.client_code || '').trim();
const message = (body.message || '').trim();
const details = body.details || {};

if (isOrchestrator) {
  // Orchestrator path — message is required, event is optional
  if (!message) throw new Error('Orchestrator payload requires a message field');
  return [{ json: {
    source: 'orchestrator',
    event: event || 'orchestrator_update',
    project_id,
    brand_name,
    client_code,
    message,
    details
  } }];
}

// Legacy path — strict event validation
const validEvents = ['research_complete', 'deck_ready', 'scripts_ready', 'delivered'];
if (!event) throw new Error('event is required (send event or event_type)');
if (!validEvents.includes(event)) {
  throw new Error('event must be one of: ' + validEvents.join(', '));
}
if (!project_id) throw new Error('project_id is required');

return [{ json: { source: 'legacy', event, project_id, brand_name, client_code, message: '', details } }];

// ============================================================
// Merge webhook payload with project details from Airtable
// Build context for Gemini prompt (legacy path only)
// ============================================================
const payload = $('Extract Webhook Payload').first().json;
const rawProject = $input.first().json;
const project = rawProject.fields
  ? { id: rawProject.id, ...rawProject.fields }
  : rawProject;

// Use Airtable data if webhook didn't provide brand_name
const brand_name = payload.brand_name || project.brand_name || 'Client';
const client_code = payload.client_code || project.client_code || '';
const client_name = project.client_name || '';
const num_scripts = project.num_scripts || 0;
const status = project.status || '';
const deck_link = project.deck_link || (payload.details || {}).deck_link || '';
const delivery_folder = project.delivery_folder || (payload.details || {}).delivery_folder || '';

// Build event context string for Gemini
const eventContextMap = {
  research_complete: `Research phase completed for ${brand_name} (${client_code}). ${num_scripts} UGC concepts have been researched. The concept deck will be prepared next. ${(payload.details || {}).concept_count ? 'Total concepts found: ' + payload.details.concept_count + '.' : ''}`,
  deck_ready: `Concept deck is ready for ${brand_name} (${client_code}). ${deck_link ? 'Deck link: ' + deck_link : 'Deck link will be shared shortly.'} The client/PM needs to review and approve concepts. ${(payload.details || {}).slide_count ? 'Deck contains ' + payload.details.slide_count + ' concept slides.' : ''}`,
  scripts_ready: `Scripts have been written for ${brand_name} (${client_code}). ${num_scripts} scripts are ready for review. ${(payload.details || {}).script_count ? payload.details.script_count + ' scripts generated.' : ''} Next step: PM review and feedback.`,
  delivered: `Final delivery completed for ${brand_name} (${client_code}). All approved scripts have been formatted into Google Docs and organized. ${delivery_folder ? 'Delivery folder: ' + delivery_folder : ''} The project is ready for creator production.`
};

return [{ json: {
  event: payload.event,
  project_id: payload.project_id,
  brand_name,
  client_code,
  client_name,
  num_scripts,
  status,
  deck_link,
  delivery_folder,
  event_context: eventContextMap[payload.event] || 'Project update for ' + brand_name,
  details: payload.details,
  source: 'legacy'
}}];

// ============================================================
// Extract Gemini response and format event notification
// Handles both orchestrator and legacy paths
// ============================================================
const geminiResponse = $input.first().json;
const candidates = geminiResponse.candidates || [];
let messageText = '';

if (candidates.length > 0 && candidates[0].content && candidates[0].content.parts) {
  messageText = candidates[0].content.parts.map(p => p.text || '').join('');
}

// Try to get context from either orchestrator or legacy path
let context;
try {
  context = $('Merge Webhook Context').first().json;
} catch(e) {
  try {
    context = $('Build Orchestrator Context').first().json;
  } catch(e2) {
    context = $('Extract Webhook Payload').first().json;
  }
}

const event = context.event;
const brand = context.brand_name;
const source = context.source || 'legacy';

// Fallback messages if Gemini fails
const fallbacks = {
  research_complete: `*${brand}* — Research phase complete. UGC concepts have been researched and compiled. Concept deck preparation is next.`,
  deck_ready: `*${brand}* — Concept deck is ready for review.${context.deck_link ? ' ' + context.deck_link : ''} Please review and approve concepts to proceed with script writing.`,
  scripts_ready: `*${brand}* — Scripts are ready for review. ${context.num_scripts} scripts have been written and are awaiting PM feedback.`,
  delivered: `*${brand}* — Final delivery complete. All approved scripts are formatted and ready for creator production.${context.delivery_folder ? ' ' + context.delivery_folder : ''}`,
  orchestrator_update: `*${brand}* — ${context.event_context || 'Project status updated.'}`
};

if (!messageText) {
  messageText = fallbacks[event] || `*${brand}* — Project update: ${event}`;
}

return [{ json: {
  slack_message: messageText,
  event,
  project_id: context.project_id,
  brand_name: brand,
  client_code: context.client_code,
  source
}}];

// ============================================================
// Error handler — captures errors from either path
// ============================================================
const err = $input.first().json;
let project_id = 'N/A';
let event = 'N/A';
try { project_id = $('Extract Webhook Payload').first().json.project_id; } catch(e) {}
try { event = $('Extract Webhook Payload').first().json.event; } catch(e) {}
return [{ json: {
  project_id,
  event,
  error_message: err.error?.message || err.message || 'Unknown error',
  error_node: err.error?.node?.name || 'Unknown',
  created_at: new Date().toISOString()
} }];

// ============================================================
// Build context for Gemini from orchestrator payload directly
// No Airtable fetch needed — orchestrator provides the message
// ============================================================
const payload = $('Extract Webhook Payload').first().json;

return [{ json: {
  event: payload.event,
  project_id: payload.project_id,
  brand_name: payload.brand_name || 'Client',
  client_code: payload.client_code || '',
  client_name: '',
  num_scripts: 0,
  status: '',
  deck_link: '',
  delivery_folder: '',
  event_context: '## Event Context (from Orchestrator)\n' + payload.message + '\n\nGenerate a professional, friendly client update based on this event. Keep it concise and action-oriented.',
  details: payload.details,
  source: 'orchestrator'
} }];
